#pragma once
#include "../../support.hpp"
#include <any>
namespace algs {
template<class T> struct Token { std::shared_ptr<const std::string> key; explicit Token(std::string description): key(std::make_shared<const std::string>(std::move(description))) {} };
template<class T> Token<T> token(std::string description) { return Token<T>(std::move(description)); }
class Container { struct Registration { std::function<std::any(Container&)> factory; bool singleton; std::optional<std::any> instance; }; std::map<std::shared_ptr<const std::string>, Registration> registrations; std::set<std::shared_ptr<const std::string>> resolving; public: template<class T, class Factory> Container& registerProvider(const Token<T>& target, Factory factory, std::string lifetime = "singleton") { if (lifetime != "singleton" && lifetime != "transient") throw std::invalid_argument("Unknown lifetime"); registrations[target.key] = {[factory = std::move(factory)](Container& container) { return std::any(T(factory(container))); }, lifetime == "singleton", {}}; return *this; } template<class T> Container& value(const Token<T>& target, T item) { registrations[target.key] = {[item](Container&) { return std::any(item); }, true, std::any(item)}; return *this; } template<class T> T resolve(const Token<T>& target) { auto it = registrations.find(target.key); if (it == registrations.end()) throw std::logic_error("No provider for " + *target.key); if (it->second.singleton && it->second.instance) return std::any_cast<T>(*it->second.instance); if (!resolving.insert(target.key).second) throw std::logic_error("Circular dependency on " + *target.key); auto factory = it->second.factory; bool singleton = it->second.singleton; try { auto item = factory(*this); resolving.erase(target.key); if (singleton) registrations.at(target.key).instance = item; return std::any_cast<T>(item); } catch (...) { resolving.erase(target.key); throw; } } };
}
